-- 211: Original BrillaPrep WASSCE BrillaPrep transitional Leatherwork beta content blueprint questions, part 9.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_211_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_211_guard;
INSERT INTO _migration_211_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_033' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_7' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What identifies appliqué as a leather-decoration method?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A knife removes a recess so a contrasting piece finishes level with the surrounding surface","B. A heated point darkens lines directly into the grain without adding another piece","C. A modelling tool makes repeated small impressions to build dotted tone and texture","D. Cut decorative pieces are arranged on a leather ground and secured by stitching, adhesive, or both"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Leather appliqué builds a design by placing separately cut motifs on top of a supporting ground and fixing their edges securely, allowing colour, texture and relief to contrast with the base. Therefore the correct answer is D: Cut decorative pieces are arranged on a leather ground and secured by stitching, adhesive, or both.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_7' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_033' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_211_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_034' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_7' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does burnishing do to a properly prepared vegetable-tanned leather edge?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It compacts and smooths exposed fibres using controlled moisture or compound and friction","B. It deposits enough adhesive to become the main structural joint","C. It raises a loose nap so the edge resembles the flesh side of suede","D. It removes a broad taper from the edge to reduce folded thickness"]' AND q.correct_answer IS 'A' AND q.explanation IS 'After levelling and bevelling, controlled friction aligns and compacts edge fibres into a smoother surface that is comfortable and more resistant to light abrasion. Therefore the correct answer is A: It compacts and smooths exposed fibres using controlled moisture or compound and friction.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_7' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_034' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_211_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_035' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_7' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which statement correctly distinguishes scorching from stippling on leather?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Scorching builds dotted texture with a pointed punch, while stippling browns the grain with a heated tool","B. Scorching uses controlled heat to darken a design, while stippling forms tone or texture with repeated small dots or impressions","C. Scorching secures cut motifs to a ground, while stippling recesses a contrasting insert flush with the surface","D. Scorching removes a thin surface layer with a knife, while stippling applies a continuous opaque dye film"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Scorching, or pyrographic work, controls a heated tool to brown the leather without burning through it; stippling accumulates separate dots or impressions to create texture, shading or emphasis. Therefore the correct answer is B: Scorching uses controlled heat to darken a design, while stippling forms tone or texture with repeated small dots or impressions.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_7' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_035' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_211_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_036' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_8' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which workshop expense is normally treated as a fixed cost when costing a batch of leather belts?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Leather consumed by each belt pattern","B. Buckles purchased for the number of belts made","C. Monthly rent for the production space","D. Packaging used for each completed belt"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Rent is incurred for the period even if output changes, while leather, buckles and unit packaging generally rise or fall with the number of belts produced. Therefore the correct answer is C: Monthly rent for the production space.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_036' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_033', 'topic_was_leatherwork_b004_7', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'What identifies appliqué as a leather-decoration method?', 'multiple_choice', NULL, '["A. A knife removes a recess so a contrasting piece finishes level with the surrounding surface","B. A heated point darkens lines directly into the grain without adding another piece","C. A modelling tool makes repeated small impressions to build dotted tone and texture","D. Cut decorative pieces are arranged on a leather ground and secured by stitching, adhesive, or both"]', 'D', 'Leather appliqué builds a design by placing separately cut motifs on top of a supporting ground and fixing their edges securely, allowing colour, texture and relief to contrast with the base. Therefore the correct answer is D: Cut decorative pieces are arranged on a leather ground and secured by stitching, adhesive, or both.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_7', 'Identify', 'AO3', NULL, NULL, 'board_waec');
