INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_035', 'topic_was_leatherwork_b004_7', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'Which statement correctly distinguishes scorching from stippling on leather?', 'multiple_choice', NULL, '["A. Scorching builds dotted texture with a pointed punch, while stippling browns the grain with a heated tool","B. Scorching uses controlled heat to darken a design, while stippling forms tone or texture with repeated small dots or impressions","C. Scorching secures cut motifs to a ground, while stippling recesses a contrasting insert flush with the surface","D. Scorching removes a thin surface layer with a knife, while stippling applies a continuous opaque dye film"]', 'B', 'Scorching, or pyrographic work, controls a heated tool to brown the leather without burning through it; stippling accumulates separate dots or impressions to create texture, shading or emphasis. Therefore the correct answer is B: Scorching uses controlled heat to darken a design, while stippling forms tone or texture with repeated small dots or impressions.', 'medium', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_7', 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_036', 'topic_was_leatherwork_b004_8', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'Which workshop expense is normally treated as a fixed cost when costing a batch of leather belts?', 'multiple_choice', NULL, '["A. Leather consumed by each belt pattern","B. Buckles purchased for the number of belts made","C. Monthly rent for the production space","D. Packaging used for each completed belt"]', 'C', 'Rent is incurred for the period even if output changes, while leather, buckles and unit packaging generally rise or fall with the number of belts produced. Therefore the correct answer is C: Monthly rent for the production space.', 'hard', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_8', 'Identify', 'AO3', NULL, NULL, 'board_waec');
